if set(_ROWS) != set(LANGUAGES):
    raise RuntimeError("Media Pool translations must define every supported language.")

TRANSLATIONS: dict[str, dict[str, str]] = {}
for _language, _values in _ROWS.items():
    if len(_values) != len(_KEYS):
        raise RuntimeError(
            f"Invalid Media Pool catalog length for {_language}: "
            f"{len(_values)} != {len(_KEYS)}"
        )
    TRANSLATIONS[_language] = dict(zip(_KEYS, _values, strict=True))


def translate_media_pool(language: str | None, key: str, **values: Any) -> str:
    """Translate Media Pool UI copy with safe English fallback."""
    locale = normalize_language(language)
    template = TRANSLATIONS.get(locale, {}).get(
        key, TRANSLATIONS[DEFAULT_LANGUAGE].get(key, key)
    )
    try:
        return template.format(**values)
    except (KeyError, ValueError):
        return template
